<script setup lang="ts">import {onMounted,ref} from 'vue';const items=ref<any[]>([]);onMounted(async()=>{const r=await fetch('/api/v1/activity');if(r.ok)items.value=await r.json()});</script>
<template><div class="hero"><div><p class="kicker">AUDIT LOG</p><h1>Activity</h1><p class="muted">A transparent record of changes in this environment.</p></div></div><div class="activity-list"><article v-for="item in items" :key="item.id"><div><strong>{{item.action}}</strong><p class="muted">{{item.resource_type}} {{item.resource_id}}</p></div><time>{{new Date(item.created_at).toLocaleString()}}</time></article><div v-if="!items.length" class="empty"><h2>No activity yet</h2><p>Important actions will appear here.</p></div></div></template>
